import java.lang.ref.Cleaner;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.LongAdder;

public final class NativeImageBuffer implements AutoCloseable {
    private static final Cleaner CLEANER = Cleaner.create();
    public static final LongAdder LEAKED_BUFFERS = new LongAdder();

    private final NativeState state;
    private final Cleaner.Cleanable cleanable;

    private static final class NativeState implements Runnable {
        private final long ptr;
        private final AtomicBoolean freed = new AtomicBoolean(false);
        private volatile boolean closedExplicitly = false;

        NativeState(long ptr) { this.ptr = ptr; }

        @Override
        public void run() {
            if (freed.compareAndSet(false, true)) {
                if (!closedExplicitly) {
                    LEAKED_BUFFERS.increment();
                }
                freeNative(ptr);
            }
        }
    }

    public NativeImageBuffer(int bytes) {
        long ptr = allocNative(bytes);
        this.state = new NativeState(ptr);
        this.cleanable = CLEANER.register(this, state);
    }

    public long address() {
        if (state.freed.get()) throw new IllegalStateException("Buffer already closed");
        return state.ptr;
    }

    @Override
    public void close() {
        state.closedExplicitly = true;
        cleanable.clean(); // Runs state.run() synchronously once & unregisters
    }

    private static native long allocNative(int bytes);
    private static native void freeNative(long ptr);
}

